attributes.custom_css:
[selector='body-container'] {
  width: 1109px;
  margin: auto;
}

[selector='btn-bx1'] {
  margin-top: 1em;
  text-align: left;
}

[selector='btn-bx1'] button {
  background-color: #2381C8;
  border-radius: 8px;
  border-color: #2381C8;
  width: 170px;
  text-transform: none;
  height: 40px;
  font-weight: bold;
  padding: 0px 15px 0px 15px;
}

[selector='left-hint'] {
  height: 22px;
  width: 310px;
  padding: 0px 14px 0px 14px;
  margin: 10px 0px 10px 0px;
}

[selector='left-hint'] div {
  display: flex;
}

[selector='left-hint'] img {
  height: 24px;
  margin-right: 15px;
}

[selector='left-hint-current'] {
  background-color: #4EA075;
  height: 52px;
  width: 330px;
  border-radius: 10px;
  padding: 13px 12px 13px 12px;
}

[selector='left-hint-current'] div {
  display: flex;
}

[selector='left-hint-current'] img {
  height: 24px;
  margin-right: 15px;
}

[selector='left-hint-current'] p {
  font-size: 19px; 
  line-height: 25.87px; 
  font-weight: 600; 
  color: white;
}

[selector='left-hint-done'] {
  height: 22px;
  width: 310px;
  padding: 0px 14px 0px 14px;
  margin: 10px 0px 10px 0px;
}

[selector='left-hint-done'] div {
  display: flex;
}

[selector='left-hint-done'] img {
  height: 20px;
  margin-right: 15px;
}

[selector='left-hint-done'] p {
  font-size: 16px; 
  line-height: 21.79px; 
  font-weight: 600; 
  color: #4EA075;
}

[selector='left-hint-fill'] {
  height: 50px;
  width: 400px;
  padding: 13px 12px 13px 12px;
}

[selector='left-hint-fill'] div {
  display: flex;
}

[selector='left-hint-fill'] img {
  height: 50px;
  margin-right: 15px;
}

[selector='arrow-button'] {
  margin-top: 1em;
  text-align: center;
}

[selector='arrow-button'] button {
  background-color: #FFFFFF;
  border-radius: 68.75px;
  width: 50px;
  height: 50px;

  background-image: url(/public-files/PLG_assets/Frame%201171275558.png);
  background-repeat: no-repeat;
  background-position: center;
}

[selector='check'] {
  text-align: center;
}

[selector='message'] {
  text-align: center;
}
